from pathlib import Path
import json,html,shutil,zipfile,csv
from PIL import Image
root=Path(__file__).parent
ads=json.loads((root/'concepte.json').read_text()); assets=json.loads((root/'imagini-surse.json').read_text()); e=html.escape
lessons=[
('Un model de mesaj pe care îl poți adapta', ['Scrie lângă contact ce informații îți sunt utile: localitatea, tipul lucrării și fotografiile relevante. Cere doar detaliile necesare pentru început.', 'Model: „Bună ziua. Lucrarea este în [localitate]. Aș dori [lucrare]. Atașez o fotografie de ansamblu și una a locului despre care vorbim.”', 'Explică următorul pas: discutați cererea și stabiliți dacă este nevoie de o vizită. Fotografiile oferă context; nu stabilesc singure diagnosticul sau prețul.']),
('O fotografie și trei repere', ['Alege o fotografie reală pentru care ai permisiune de publicare. Evită cadrele cu date personale sau detalii de identificare ale locuinței.', 'Completează: ce ai realizat, în ce tip de spațiu și ce detaliu merită observat. Exemplu de structură: „[Lucrare] într-un [tip de spațiu]. În imagine se vede [detaliu relevant].”', 'Încheie cu serviciul asociat și modul de contact. Descrierea ajută cititorul să înțeleagă proiectul; nu reprezintă o promisiune că orice lucrare va fi identică.']),
('Zona de lucru, în cuvinte simple', ['Pornește de la localitățile în care te deplasezi efectiv. Scrie numele lor, fără să presupui că cititorul cunoaște cartierele sau limitele unei hărți.', 'Model: „Lucrăm în [localități]. Pentru alte zone, discutăm disponibilitatea în funcție de lucrare.” Folosește modelul doar dacă descrie practica ta reală.', 'Dacă există condiții de deplasare, explică-le înainte de confirmare. Pune lista lângă serviciu și contact, apoi verifică dacă este ușor de găsit pe telefon.']),
('Traseul de la lucrare la conversație', ['Deschide o lucrare din portofoliu. Lângă fotografie, explică ce serviciu ai realizat și ce poate solicita cititorul.', 'Adaugă o invitație concretă, de exemplu: „Discutăm o lucrare asemănătoare”. Leag-o de canalul de contact pe care îl folosești.', 'Testează traseul pe telefon: fotografie → explicație → contact. Verifică dacă butonul deschide destinația corectă. O apăsare pe buton nu este automat o conversație sau un client.']),
('Pagina care însoțește o recomandare', ['Pune la început numele sub care lucrezi și serviciile principale. Adaugă zona în care te deplasezi.', 'Selectează lucrări reale și explică pe scurt ce ai făcut. O persoană care primește linkul trebuie să poată înțelege oferta fără să te cunoască deja.', 'Încheie cu un contact vizibil. Deschide linkul pe telefon și verifică titlul, imaginea de previzualizare și informațiile. Recomandarea din reclamă este un scenariu, nu o mărturie.']),
('Întrebarea care aduce context', ['Pentru un calorifer, „Este o înlocuire sau un montaj nou?” separă două situații despre care poți avea nevoie de informații diferite.', 'Cere apoi localitatea și o fotografie de ansamblu a locului. Evită să transformi începutul discuției într-un formular prea lung.', 'Precizează că detaliile tehnice și soluția se stabilesc după evaluare. Pentru alte servicii, pornește de la întrebarea care îți este cu adevărat utilă în practică.']),
('Ansamblu și detaliu', ['Fotografia de ansamblu arată spațiul și amplasarea. Fotografia de detaliu arată zona despre care se discută.', 'Model de cerere: „Trimite o fotografie a spațiului și una a locului unde dorești montajul, făcute dintr-o poziție sigură, fără demontări.”', 'Cere să fie evitate persoanele și informațiile personale din cadru. Folosește imaginile pentru context și clarificări; evaluarea lucrării rămâne un pas separat.']),
('De la listă la prezentarea serviciilor', ['Scrie servicii concrete: montaj baterii, înlocuire obiecte sanitare sau montaj calorifere, doar dacă acestea fac parte din activitatea ta.', 'Pentru fiecare serviciu, completează: „Ce facem”, „Unde lucrăm” și „Ce ne spui la primul contact”. Evită formulările prea generale, precum „soluții complete”, fără explicație.', 'Pune lângă fiecare o imagine relevantă și următorul pas. Verifică dacă o persoană fără vocabular tehnic poate recunoaște lucrarea pe care vrea să o solicite.']),
('Cum povestești un proiect real', ['Alege etapele care ajută cititorul să înțeleagă lucrarea: situația inițială, un moment relevant din montaj și rezultatul final.', 'Folosește numai fotografii din același proiect și descrie ce ai realizat în fiecare. Menționează dacă o imagine este ilustrativă.', 'Nu prezenta imaginile drept certificare tehnică sau dovadă de performanță comercială. Portofoliul poate explica procesul și tipurile de lucrări pe care le faci.']),
('Două programe care merită explicate', ['Programul de contact spune când preiei apeluri sau mesaje. Disponibilitatea pentru lucrări se confirmă separat, după cerere.', 'Model: „Preluăm apeluri în [interval real]. Data intervenției se stabilește după discutarea lucrării.” Completează doar intervalele pe care le poți respecta.', 'Așază explicația lângă telefon și actualizeaz-o când se schimbă. Evită să sugerezi preluare permanentă sau intervenție imediată dacă nu le oferi.']),
('Întrebările care vin din practică', ['Notează întrebările pe care le primești efectiv înainte de o lucrare. Alege-le pe cele care clarifică serviciile și modul de colaborare.', 'Structură de răspuns: ce oferi, în ce condiții și ce trebuie discutat înainte de confirmare. Exemplul despre schimbarea unei singure baterii se folosește doar dacă preiei astfel de lucrări.', 'Păstrează răspunsurile scurte și actualizate. Adaugă contact pentru situațiile care au nevoie de evaluare individuală.']),
('Ce vede omul după scanare', ['Pregătește o pagină cu servicii, lucrări reale, zonă și contact. Folosește o adresă stabilă, pe care o controlezi.', 'Dacă adaugi un cod QR pe cartea de vizită, generează-l pentru acea adresă și testează o probă tipărită pe mai multe telefoane.', 'Include și adresa lizibilă. Codul din vizualul reclamei este o reprezentare ilustrativă, nu un cod de folosit la tipar. Realizarea materialelor tipărite se discută separat de site.']),
('Testul de pe propriul telefon', ['Deschide pagina și caută serviciile, zona și contactul. Notează exact unde o informație este greu de găsit sau de citit.', 'Apasă butoanele de contact și verifică numărul, aplicația și destinația. Dacă există formular, verifică și confirmarea trimiterii printr-un test controlat.', 'Repetă pe încă un ecran, dacă ai posibilitatea. Testul verifică experiența observată; rezultatele comerciale se urmăresc separat.']),
('O solicitare care pregătește oferta', ['Cere tipul lucrării, localitatea și dacă obiectul care trebuie montat este deja cumpărat. Adaptează lista la serviciul concret.', 'Explică pașii: clarificarea cererii, evaluarea sau vizita dacă este necesară, apoi discutarea ofertei și a condițiilor.', 'Nu prezenta această listă ca pe un calculator automat de preț. Costul se stabilește în funcție de lucrarea evaluată și de acordul dintre părți.']),
('Un brief scurt pentru actualizarea site-ului', ['Alege serviciul pe care vrei să îl aduci în prim-plan și verifică dacă îl poți prelua în perioada respectivă.', 'Trimite un brief cu denumirea serviciului, explicația, zona acoperită, o fotografie reală cu drept de utilizare și contactul corect.', 'Cere actualizarea prezentării și verifică varianta pe telefon. Amploarea schimbării și termenul se confirmă în funcție de plan și solicitare.']),
]
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f5ef;color:#242320;font:16px/1.6 Arial,sans-serif}main{max-width:1280px;margin:auto;padding:40px 24px}h1{font-size:clamp(40px,6vw,76px);line-height:1.04;letter-spacing:-.045em;max-width:900px}h1 em{color:#d9532b;font-style:normal}h2{font-size:30px;line-height:1.2;letter-spacing:-.025em}a{color:inherit;text-underline-offset:4px}.tag{color:#a64020;font-size:13px;font-weight:bold}.note{padding:18px;background:#eae4d9;border-left:3px solid #d9532b;max-width:950px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin:40px 0}.grid a{text-decoration:none}.grid img{width:100%;display:block}.grid span{display:block;margin-top:8px;font-size:14px}.layout{display:grid;grid-template-columns:1fr 1fr;gap:40px}.layout img{width:100%;display:block}.copy p{margin:0 0 18px}.copy p:first-child{font-size:21px}article{border-top:1px solid #cbc5b9;padding:28px 0;margin:35px 0;scroll-margin-top:20px}.link{background:#242320;color:#f7f5ef;padding:20px;margin:20px 0}.link p{margin:8px 0}.cta{border:1px solid #999;padding:6px 12px;display:inline-block}details{margin-top:25px;overflow-wrap:anywhere}summary{cursor:pointer;font-weight:bold}.tools{display:flex;gap:25px;flex-wrap:wrap}.reading{max-width:780px}.reading p{font-size:19px}.step{color:#a64020;font-weight:bold}.offer{background:#eae4d9;padding:24px;margin-top:25px}@media(max-width:760px){main{padding:24px 16px}.grid{grid-template-columns:repeat(2,1fr);gap:14px}.layout{grid-template-columns:1fr;gap:24px}h2{font-size:26px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
def page(title,body):return '<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+'</title><style>'+css+'</style></head><body><main>'+body+'</main></body></html>'
for asset in assets:
 shutil.copy2(asset['source'],root/asset['file'])
 with Image.open(root/asset['file']) as im:
  im.verify()
 with Image.open(root/asset['file']) as im:
  assert im.mode=='RGB' or (im.mode=='RGBA' and im.getextrema()[-1]==(255,255))
  asset['size']=list(im.size)
(root/'imagini-surse.json').write_text(json.dumps(assets,ensure_ascii=False,indent=2))
assert len(assets)==16
md='# 16 reclame Meta pentru instalatori — WebForm\n\nPaletă actuală: crem, cărbune, portocaliu. Imagini generate cu ImageGen integrat. Fiecare scenă este ilustrativă, nu portofoliu sau dovadă de rezultat. CTA: Learn more.\n\nGhid aplicat: Ghid-universal-reclame-care-starnesc-curiozitatea.pdf, toate cele 13 pagini. Pachet de creație, nepublicat. Continuările 1–15 sunt incluse în continuari.html și trebuie publicate pe site înainte de lansare. Reclama 16 trimite la pagina /instalatii existentă în cod, de verificat live. Nu sunt incluse prețuri sau rezultate comerciale.\n\n'
cards=[];thumbs=[]
fields=[('Public','audience'),('Situație','situation'),('Ipoteza conceptului','hypothesis'),('Beneficiu concret','benefit'),('Baza afirmațiilor','basis'),('Scena principală','scene'),('Inserția și rolul ei','inset'),('Destinație','destination'),('Promisiunea continuării','lesson'),('Starea publicării','publication'),('De verificat','verify')]
for a in ads:
 md+=f"## {a['id']:02d}. {a['headline']}\n\n**Fișier:** {a['file']}\n\n### Text principal\n\n{a['copy']}\n\n**Hook-uri alternative:**\n\n- {a['alternatives'][0]}\n- {a['alternatives'][1]}\n\n**Titlu link:** {a['link']}\n\n**Descriere:** {a['description']}\n\n**CTA:** Learn more\n\n"
 for label,key in fields:md+=f'**{label}:** {a[key]}\n\n'
 md+=f"**Text exact în imagine:** {a['headline']} · Exemplu ilustrativ · webform\n\n**Prompt final:**\n\n{a['prompt']}\n\n"
 paragraphs=''.join('<p>'+e(p)+'</p>' for p in a['copy'].split('\n\n'))
 meta=''.join('<p><b>'+label+':</b> '+e(a[key])+'</p>' for label,key in fields)
 target=a['destination'] if a['id']<16 else 'https://ro.joinwebform.com/instalatii'
 cards.append(f'<article id="reclama-{a["id"]}"><div class="tag">{a["id"]:02d} / {e(a["angle"])}</div><h2>{e(a["headline"])}</h2><div class="layout"><div><a href="{a["file"]}"><img loading="lazy" src="{a["file"]}" alt="{e(a["headline"])}"></a><p><a download href="{a["file"]}">Descarcă imaginea ↗</a></p></div><div class="copy">{paragraphs}<div class="link"><b>{e(a["link"])}</b><p>{e(a["description"])}</p><span class="cta">Learn more</span></div><p><a href="{target}">Vezi continuarea ↗</a></p><b>Hook-uri alternative</b><ul>'+''.join('<li>'+e(x)+'</li>' for x in a['alternatives'])+'</ul></div></div><details><summary>Brief, bază factuală și prompt</summary>'+meta+'<p><b>Prompt final:</b> '+e(a['prompt'])+'</p></details></article>')
 thumbs.append(f'<a href="#reclama-{a["id"]}"><img src="{a["file"]}" alt="{e(a["headline"])}"><span><b>{a["id"]:02d}</b> · {e(a["angle"])}</span></a>')
(root/'16-reclame-complete.md').write_text(md)
intro='<div class="tag">webform / campanie instalatori</div><h1>16 idei.<br><em>O meserie în prim-plan.</em></h1><p>Reclame cu situații recognoscibile, sfaturi aplicabile și curiozitate în jurul unui detaliu concret.</p><div class="tools"><a href="16-reclame-complete.md">Toate textele și prompturile ↗</a><a href="continuari.html">Continuările după click ↗</a><a href="../webform-16-reclame-instalatori.zip">Pachetul complet ZIP ↗</a></div><p class="note">Imagini ilustrative generate cu ImageGen. Reclamele și continuările nu sunt publicate. Publică explicația corespunzătoare înainte de lansarea fiecărei reclame. Buton Meta: <b>Learn more</b>.</p>'
(root/'galerie.html').write_text(page('WebForm — 16 reclame pentru instalatori',intro+'<nav class="grid">'+''.join(thumbs)+'</nav>'+''.join(cards)))
continuations='<div class="tag">webform / materiale pentru destinația clickului</div><h1>Ideea din reclamă.<br><em>Explicația completă.</em></h1><p class="note">Materiale editoriale pregătite pentru publicare. Aceasta este o previzualizare locală. Fiecare secțiune poate deveni o pagină dedicată.</p><p><a href="galerie.html">Înapoi la reclame ↗</a></p>'
for a,(title,paras) in zip(ads,lessons):
 continuations+=f'<article class="reading" id="reclama-{a["id"]}"><div class="tag">{a["id"]:02d} / {e(a["angle"])}</div><h2>{e(title)}</h2>'+''.join(f'<p><span class="step">{j}.</span> {e(p)}</p>' for j,p in enumerate(paras,1))+'<div class="offer"><b>Cum putem ajuta</b><p>Noi putem organiza aceste informații într-un site pentru activitatea ta de instalații. Conținutul se adaptează serviciilor și modului tău de lucru.</p><a href="https://ro.joinwebform.com/instalatii">Vezi exemplul de site și condițiile colaborării ↗</a></div></article>'
(root/'continuari.html').write_text(page('WebForm — continuările reclamelor pentru instalatori',continuations))
with (root/'texte-reclame.csv').open('w',newline='',encoding='utf-8-sig') as f:
 keys=['id','file','headline','copy','link','description','cta','destination','publication'];w=csv.DictWriter(f,fieldnames=keys);w.writeheader();w.writerows({k:a[k] for k in keys} for a in ads)
(root/'README.md').write_text('''# Pachet WebForm — 16 reclame pentru instalatori

Deschide `galerie.html` pentru toate imaginile și textele.

- 16 PNG-uri originale, fundal opac, format portret apropiat de 4:5; dimensiunile exacte sunt în `imagini-surse.json`.
- `16-reclame-complete.md`: texte, 32 hook-uri alternative, briefuri, surse de afirmații și prompturile finale.
- `texte-reclame.csv`: texte structurate pentru copiere; nu este un fișier garantat compatibil cu importul automat Meta.
- `continuari.html`: 15 continuări editoriale, pregătite dar nepublicate. Reclama 16 se referă la pagina de instalații din proiect.
- `concepte.json`: sursa editabilă a conceptelor.

Generare: ImageGen integrat. Designul actual este preluat din REDESIGN_NOTES.md, app/globals.css și reclamele existente: crem, cărbune, portocaliu. DESIGN.md descrie o variantă anterioară.

Publicare: nu s-au lansat reclame, nu s-a cheltuit buget și nu s-au publicat paginile. Înainte de lansare, fiecare reclamă trebuie legată la continuarea corectă publicată, iar oferta live verificată. Nu utiliza imaginile generate drept portofoliu real de instalații.
''')
archive=root.parent/'webform-16-reclame-instalatori.zip'
with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED) as z:
 for p in sorted(root.iterdir()):
  if p.suffix in ['.png','.html','.md','.json','.csv']:z.write(p,root.name+'/'+p.name)
with zipfile.ZipFile(archive) as z:
 assert z.testzip() is None
 assert len([n for n in z.namelist() if n.endswith('.png')])==16
print('16 PNG-uri, 32 alternative, 15 continuări, galerie, texte și ZIP verificate.')
